#!/bin/bash
# Run all ZCU102 bundles (generated by collect_hw_bundles.py). usage: sudo ./run_all.sh [Dir ...]
set -u
cd "$(dirname "$0")/.."
#### JO added (2026-11-04): --help; the output starts with the bitstream and its features (../bininfo.sh)
case " $* " in *" -h "*|*" --help "*) echo "usage: sudo $0 [Dir ...]   (in hw*/script/; no Dir = every run line)"
  echo "  Reloads BIN (below; BIN=<file in /lib/firmware> in the environment wins) before each run line, runs the executable,"
  echo "  compares output.bin with the golden -> result/results.txt. HLS vtalib executables (build${PWD##*/hw}/)."
  echo "  Timing runs and the systolic bitstream (SYS_BIN): script/run_prof.sh --help"
  for v in BIN SYS_BIN; do d=$(sed -n 's/^'$v'=\${'$v':-\(.*\)}$/\1/p; s/^'$v'=\([^$].*\)$/\1/p' script/run_all.sh)
    [ -n "$d" ] && echo "  $v of script/run_all.sh: $d$([ -f /lib/firmware/$d ] || echo '  (not in /lib/firmware)')"; done
  [ -n "${BIN:-}" ] && echo "  BIN= in the environment: $BIN (used instead)"
  exit 0;; esac
[ -n "${BIN:-}" ] && BSRC="BIN= in the environment" || BSRC="BIN of $0"
BIN=${BIN:-vtahw_zcu102_1x16_i8w8a32_16_15_18_17_4evta_380mhz.bin}
#### JO changed (2026-11-04): SYS_BIN = the ALU imm II 1 systolic bitstream (bit/evta_multi4_alu1_400MHz_pass_261104)
#SYS_BIN=${SYS_BIN:-vtahw_zcu102_1x16_i8w8a32_16_15_18_17_4evta_sa_400mhz.bin}
#### JO changed (2026-11-04): SYS_BIN = the bias reset build (bit/evta_multi4_bias_400MHz_pass_261104)
#SYS_BIN=${SYS_BIN:-vtahw_zcu102_1x16_i8w8a32_16_15_18_17_4evta_sa_400mhz_alu1.bin}
#### JO changed (2026-11-04): SYS_BIN = the requantize build at 395.8 MHz (bit/evta_multi4_rq_396MHz_pass_261104; 400 MHz missed by 7 ps)
#SYS_BIN=${SYS_BIN:-vtahw_zcu102_1x16_i8w8a32_16_15_18_17_4evta_sa_400mhz_bias.bin}
SYS_BIN=${SYS_BIN:-vtahw_zcu102_1x16_i8w8a32_16_15_18_17_4evta_sa_396mhz_rq.bin}
export OMP_NUM_THREADS=${OMP_NUM_THREADS:-1}
[ "$(id -u)" = 0 ] || { echo "run with sudo"; exit 1; }
exec 9>/tmp/evta_run.lock; flock -n 9 || { echo "another EVTA run is active (/tmp/evta_run.lock)"; exit 1; }
ONLY="$*"
mkdir -p result trace; : > result/results.txt
#### JO added (2026-11-04): what this run is, at the start of the output and of result/results.txt
. ../bininfo.sh
{ echo "== run_all.sh ${PWD##*/} $(date '+%F %T')"; echo "  bitstream from $BSRC"; bin_info $BIN
  echo "  OMP_NUM_THREADS: $OMP_NUM_THREADS   Dirs: ${ONLY:-every run line}"; } | tee -a result/results.txt; echo
LOG() { echo $1.log; }  # log name for executable $1
run() {  # dir exe input golden
  [ -n "$ONLY" ] && [[ " $ONLY " != *" $1 "* ]] && return
  echo "================ $1 ($2)"
  echo 0 > /sys/class/fpga_manager/fpga0/flags
  if for i in $(seq 24); do echo $BIN > /sys/class/fpga_manager/fpga0/firmware 2>/dev/null && break; [ $i = 1 ] && ( mkdir -p /tmp/xlnk_trace && cd /tmp/xlnk_trace && python3 -c "from pynq import Xlnk; Xlnk().xlnk_reset()" 2>/dev/null ); sleep 5; false; done; then echo $BIN > /tmp/evta_bitstream
  else echo "FAILED $BIN" > /tmp/evta_bitstream; echo "bitstream $BIN: load failed"; fi
  ( cd trace && python3 -c "from pynq import Xlnk; Xlnk().xlnk_reset()" 2>/dev/null )
  ( cd $1 && rm -f output.bin && timeout -k 10 300 ./$2 $3 > $(LOG $2) 2>&1; echo $? > $(LOG $2).rc )
  rc=$(cat $1/$(LOG $2).rc); chown -R --reference=. $1
  if [ $rc = 124 ]; then res=TIMEOUT
  elif [ $rc != 0 ]; then res="FAIL(rc=$rc)"
  elif [ -n "$4" ]; then cmp -s $1/output.bin $1/$4 && res=PASS || res=MISMATCH
  else res="RAN (no golden; see $1/$(LOG $2))"; fi
  r=$(grep -a '^RESULT mask' $1/$(LOG $2) | sed 's/^RESULT mask [^:]*: //; s/, all = golden//')
  if [ -n "$r" ]; then grep -aE '^(EVTA[0-9]+: |RESULT mask)' $1/$(LOG $2); else tail -3 $1/$(LOG $2); fi
  printf "%-30s %-34s %s\n" $1 $2 "$res${r:+  $r}" | tee -a result/results.txt
}
run MultiEVTAConv4Test multi4conv4Bundle '15 100' vtaConv4TestGolden.bin
run MultiEVTAConvTest multievtaConvTestBundle multievtaConvTestInput.bin multievtaConvTestGolden0.bin
run MultiEVTAResConv10Test multi4resconv10Bundle '15 100' vtaResConv10TestGolden.bin
run MultiEVTAResnet18Test multivtaMxnetResnet18Bundle /home/xilinx/JO/npuprg/nestc2_clion/nest-compiler/glow/tests/images/imagenet/cat_285.png ''
run MultiEVTAResnet18Test singlevtaMxnetResnet18Bundle /home/xilinx/JO/npuprg/nestc2_clion/nest-compiler/glow/tests/images/imagenet/cat_285.png ''
echo; echo "== summary"; cat result/results.txt
